SELECT c.relname,c.relrowsecurity FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('news_categories','event_types','download_categories') ORDER BY c.relname;
SELECT table_name,column_name,data_type,is_nullable,column_default FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('news_categories','event_types','download_categories') ORDER BY table_name,ordinal_position;
SELECT tablename,indexname,indexdef FROM pg_indexes WHERE schemaname='public' AND tablename IN ('news_categories','event_types','download_categories') ORDER BY tablename,indexname;
SELECT event_object_table,trigger_name,event_manipulation,action_statement FROM information_schema.triggers WHERE event_object_schema='public' AND event_object_table IN ('news_categories','event_types','download_categories') ORDER BY event_object_table,trigger_name;
SELECT tablename,policyname,roles,cmd,qual,with_check FROM pg_policies WHERE schemaname='public' AND tablename IN ('news_categories','event_types','download_categories') ORDER BY tablename,cmd,policyname;
SELECT tablename,policyname,cmd FROM pg_policies WHERE schemaname='public' AND tablename IN ('news_categories','event_types','download_categories') AND cmd<>'SELECT' AND (coalesce(qual,'')='true' OR coalesce(with_check,'')='true' OR coalesce(qual,'') ILIKE '%app_metadata%' OR coalesce(with_check,'') ILIKE '%app_metadata%');
SELECT 'news_categories' source,slug,name_de,name_en,is_active,sort_order,false is_system FROM public.news_categories UNION ALL SELECT 'event_types',slug,name_de,name_en,is_active,sort_order,is_system FROM public.event_types UNION ALL SELECT 'download_categories',slug,name_de,name_en,is_active,sort_order,false FROM public.download_categories ORDER BY source,sort_order,slug;
